import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";
import "./css/quiz.css";

function JoinQuiz() {
   // for the space background
     useEffect(() => {
         if (location.pathname !== "/host") return;
         const starsContainer = document.getElementById("stars");
 
         if (!starsContainer) return;
         starsContainer.innerHTML = "";
 
         for (let i = 0; i < 180; i++) {
             const star = document.createElement("div");
 
             const size =
                 Math.random() > 0.96
                     ? "lg"
                     : Math.random() > 0.7
                         ? "md"
                         : "sm";
 
             star.className = `star ${size}`;
 
             star.style.left = Math.random() * 100 + "%";
             star.style.top = Math.random() * 100 + "%";
 
             star.style.animationDuration =
                 2 + Math.random() * 6 + "s";
 
             star.style.animationDelay =
                 Math.random() * 5 + "s";
 
             starsContainer.appendChild(star);
         }
     }, [location.pathname]);
 

  const navigate = useNavigate();
  const [quizCode, setQuizCode] = useState("");
  const handleJoin = () => {
    if (!quizCode.trim()) {
      alert("Please enter the quiz code.");
      return;
    }

    navigate("/quiz");
  };

  return (
    <div className="min-vh-100 d-flex align-items-center justify-content-center py-5">
      <div
        className="modal-bg rounded-4 p-4 p-lg-5"
        style={{ maxWidth: "700px", width: "100%" }}
      >
        {/* Heading */}
        <h2 className="text-center fw-bold mb-4">
          Join Quiz
        </h2>

        {/* Quiz Code */}
        <div className="mb-4">
          <label className="form-label fw-bold">
            Enter Quiz Code
          </label>

          <input
            type="text"
            className="form-control form-control-lg"
            placeholder="Enter 6 digit quiz code"
            value={quizCode}
            onChange={(e) => setQuizCode(e.target.value)}
          />
        </div>

        {/* Instructions */}
        <div className="border rounded-3 p-4 bg-light mb-4">
          <h5 className="fw-bold mb-3">
            Instructions
          </h5>

          <ul className="mb-0">
            <li>Read each question carefully before answering.</li>
            <li>Select only one answer for each question.</li>
            <li>Do not refresh or close the browser.</li>
            <li>Each question has a limited time.</li>
            <li>Once submitted, answers cannot be changed.</li>
          </ul>
        </div>

        {/* Button */}
        <div className="d-grid">
          <button
            className="btn btn-success btn-lg fw-bold"
            onClick={handleJoin}
          >
            I Agree & Continue
          </button>
        </div>
      </div>
    </div>
  );
}

export default JoinQuiz;
